// Exact half-cell blocking from the original client SEG Layer3.
const MainlandPassability=(()=>{const data=Uint8Array.from(atob(''),c=>c.charCodeAt(0));function edge(x,y,which){x-=32960;y-=33280;if(x<0||y<0||x>=256||y>=256)return null;return !(data[(y*256+x)*2+which]&1);}function cardinal(x,y,dx,dy){return dx===1?edge(x,y,1):dx===-1?edge(x-1,y,1):dy===-1?edge(x,y,0):edge(x,y+1,0);}function canTraverse(x,y,dx,dy){if(window.activeMapId!==4)return null;if(!dx||!dy)return cardinal(x,y,dx,dy);const edges=[cardinal(x,y,dx,0),cardinal(x,y,0,dy),cardinal(x+dx,y,0,dy),cardinal(x,y+dy,dx,0)];return edges.includes(null)?null:edges.every(Boolean);}return {canTraverse};})();window.MainlandPassability=MainlandPassability;